import React from 'react';
import PropTypes from 'prop-types';
import { Link } from 'react-router-dom';
import { FaLeaf, FaDrumstickBite, FaUtensils, FaMapMarkerAlt } from 'react-icons/fa';
import { Card, CardContent } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { cn } from '../../lib/utils';
import RecommendationBadge from './RecommendationBadge';
import ReviewBadge from './ReviewBadge';
import { displayDistance } from '../../utils/distance';

// ── Mess type config ─────────────────────────────────────────────────────────
const getMessTypeInfo = (type) => {
    switch (type) {
        case 'veg':     return { icon: FaLeaf,          text: 'Pure Veg',     color: 'text-green-700', bg: 'bg-green-50',  border: 'border-green-200' };
        case 'both':    return { icon: FaUtensils,       text: 'Veg & Non-Veg',color: 'text-orange-600',bg: 'bg-orange-50', border: 'border-orange-200' };
        case 'non-veg': return { icon: FaDrumstickBite,  text: 'Non-Veg',      color: 'text-red-600',   bg: 'bg-red-50',    border: 'border-red-200' };
        default:        return { icon: FaUtensils,       text: 'Type N/A',     color: 'text-gray-500',  bg: 'bg-gray-50',   border: 'border-gray-200' };
    }
};

// ── Price resolver ────────────────────────────────────────────────────────────
const resolvePrice = (mess) => {
    let raw = mess.price_per_month;
    if (mess.pricing?.monthlyTwoTime) raw = mess.pricing.monthlyTwoTime;
    if (typeof raw === 'object' && raw !== null) {
        return Number(raw.monthlyTwoTime || raw.fullTiffin || 0);
    }
    const n = Number(raw);
    return isNaN(n) ? 0 : n;
};

// ── Component ─────────────────────────────────────────────────────────────────
const MessCard = ({ mess, recommendationScore = null, matchReasons = null }) => {
    if (!mess) return null;

    const {
        mess_id,
        cover_photo_url,
        name,
        description,
        address,
        menu = {},
        rating,
        reviewCount,
    } = mess;

    const displayPrice  = resolvePrice(mess);
    const messTypeInfo  = getMessTypeInfo(menu.type);
    const menuItems     = [...(menu.vegItems || []), ...(menu.nonVegItems || [])];
    const highlightItems = menuItems.slice(0, 3);
    const remainingCount = menuItems.length > 3 ? menuItems.length - 3 : 0;

    return (
        <Card className="relative overflow-hidden shadow-md hover:shadow-lg transition-shadow duration-300 group border border-gray-200 bg-white h-full flex flex-col py-0">

            {/* ── Image — no overflow-hidden so RecommendationBadge tooltip floats freely ── */}
            <div className="relative h-52">
                <Link to={`/mess/${mess_id}`} className="block h-full">
                    {cover_photo_url ? (
                        <img
                            src={cover_photo_url}
                            alt={name || 'Mess Image'}
                            className="w-full h-52 object-cover"
                            loading="lazy"
                        />
                    ) : (
                        <div className="w-full h-52 bg-gray-200 flex items-center justify-center">
                            <span className="text-gray-500">No Image Available</span>
                        </div>
                    )}
                </Link>

                {/* Price badge — consistent green-700 across all cards */}
                <Badge
                    variant="secondary"
                    className="absolute top-3 right-3 bg-green-700 text-white font-bold border-none text-sm py-1 px-3"
                >
                    ₹{displayPrice.toLocaleString('en-IN')} /mo
                </Badge>
            </div>

            {/* RecommendationBadge — outside image div, relative to Card,
                so its tooltip can float over card content without being clipped */}
            <RecommendationBadge
                score={recommendationScore}
                reasons={matchReasons}
                className="top-11 right-3"
            />

            {/* ── Card body ── */}
            <CardContent className="p-4 py-2 gap-2 flex-grow flex flex-col">

                {/* Title + Rating */}
                <div className="flex justify-between items-start gap-2">
                    <h3 className="text-lg font-bold text-gray-800 truncate group-hover:text-primary transition-colors flex-1">
                        <Link to={`/mess/${mess_id}`}>{name || 'Unnamed Mess'}</Link>
                    </h3>
                    <ReviewBadge rating={rating} count={reviewCount} className="flex-shrink-0" />
                </div>

                {/* Description — always rendered with min-h so cards without long text stay same height */}
                <p className="text-sm text-gray-600 line-clamp-2 min-h-[2.5rem]">
                    {description || ''}
                </p>

                {/* Location + Distance */}
                <div className="flex items-start gap-1 text-gray-600 text-sm">
                    <FaMapMarkerAlt className="w-4 h-4 text-green-700 flex-shrink-0 mt-0.5" />
                    <span className="break-words line-clamp-2 flex-1">
                        {address || 'Near Campus'}
                    </span>
                    {mess.distance !== undefined && mess.distance !== null && (() => {
                        const dist = displayDistance(mess.distance, mess.distanceIsExact);
                        return dist !== null ? (
                            <Badge variant="outline" className="ml-1 py-0.5 px-1.5 text-xs whitespace-nowrap flex-shrink-0 text-green-700 border-green-300 mt-0.5">
                                ~{dist} km
                            </Badge>
                        ) : null;
                    })()}
                </div>

                {/* Mess Type pill + Menu item badges — min-h keeps button aligned */}
                <div className="flex flex-wrap items-center gap-1 min-h-[3rem] content-start">
                    {/* Mess type pill — styled like availability badge on RoomCard */}
                    <div className={cn(
                        'flex items-center gap-1 text-xs font-semibold px-2 py-0.5 rounded border',
                        messTypeInfo.bg,
                        messTypeInfo.color,
                        messTypeInfo.border
                    )}>
                        <messTypeInfo.icon className="w-3 h-3" />
                        <span>{messTypeInfo.text}</span>
                    </div>

                    {highlightItems.map((item, index) => (
                        <Badge key={index} variant="outline" className="py-0.5 px-1.5 font-normal text-xs">
                            {item}
                        </Badge>
                    ))}

                    {remainingCount > 0 && (
                        <Badge variant="outline" className="py-0.5 px-1.5 font-normal text-xs">
                            +{remainingCount}
                        </Badge>
                    )}
                </div>

                {/* View Details Button — mt-auto pushes it to bottom */}
                <Link to={`/mess/${mess_id}`} className="block w-full mt-auto pt-2">
                    <Button
                        variant="default"
                        className="w-full bg-green-700 hover:bg-green-800 text-white font-semibold rounded-lg py-2 flex items-center justify-center gap-2"
                    >
                        View Details
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                        </svg>
                    </Button>
                </Link>
            </CardContent>
        </Card>
    );
};

MessCard.propTypes = {
    mess:                PropTypes.object,
    recommendationScore: PropTypes.number,
    matchReasons:        PropTypes.array,
};

export default React.memo(MessCard);
